    /** @return array<string,string> slug => nama, sesuai urutan pemilih */
    public static function all(): array
    {
        return array_map(fn (array $i) => $i[0], self::ICONS);
    }

    /** Slug dikenal? */
    public static function has(mixed $slug): bool
    {
        return is_string($slug) && isset(self::ICONS[$slug]);
    }

    /** Nama merek, atau '' untuk slug yang tidak dikenal. */
    public static function title(mixed $slug): string
    {
        return self::has($slug) ? self::ICONS[$slug][0] : '';
    }

    /** Jalur SVG (kanvas 24x24), atau '' untuk slug yang tidak dikenal. Aman dicetak dengan {{ }}. */
    public static function path(mixed $slug): string
    {
        return self::has($slug) ? self::ICONS[$slug][1] : '';
    }

    /**
     * Tebak slug dari alamat (host persis atau subdomainnya: "id.linkedin.com" -> linkedin). null bila tidak dikenal / bukan http(s).
     */
    public static function detect(mixed $url): ?string
    {
        $u = is_string($url) ? trim($url) : '';
        if (!preg_match('#^https?://([^/:?\#\s]+)#i', $u, $m)) {
            return null;
        }
        $host = strtolower($m[1]);
        $host = preg_replace('/^(?:www|m|mobile)\./', '', $host) ?? $host;
        while ($host !== '') {
            if (isset(self::HOSTS[$host])) {
                return self::HOSTS[$host];
            }
            $dot = strpos($host, '.');
            if ($dot === false || substr_count($host, '.') < 2) {
                break;   // sisakan domain dua bagian: "com" tidak dicocokkan
            }
            $host = substr($host, $dot + 1);
        }

        return null;
    }

    /** Slug yang dipakai tampil: yang dipilih bila dikenal, selain itu tebakan dari tautan, selain itu ''. */
    public static function resolve(mixed $chosen, mixed $url): string
    {
        return self::has($chosen) ? (string) $chosen : (self::detect($url) ?? '');
    }
}
